-- CC_0531_palm_desert_city_government.sql
-- CC_0531: City of Palm Desert, CA (place 0655184, Riverside County) -- the city council, which did not exist, built
-- part-way through its switch to district elections. CC_0533 finishes the switch on or after 2026-12-10.
--
-- WHAT WAS THERE (read 2026-11-28). Only the TIGER G4110 outline 'Palm Desert city' (geo_id '0655184'). No government,
-- chamber, district, office or person. (Schools: Desert Sands Unified, CC_0524 -- Palm Desert City Hall is in DSUSD
-- Trustee Area 1.)
--
-- THE COUNCIL. palmdesert.gov/government/city-council (read 2026-11-28; Akamai blocks curl, read with headless Chrome):
-- "a charter city ... five members elected to four-year terms. Each year, the Mayor is selected from among the Council
-- to serve a one-year term." -> NO separately elected Mayor; Mayor and Mayor Pro Tem are council-chosen roles, kept in
-- office descriptions, not titles (Duvall ruling 5). The roster, with the page's own district and term lines:
--   Evan Trubee, Mayor -- "Current term: 2022-2026", "At-Large"
--   Joe Pradetto, Mayor Pro Tem -- "Current term: 2024-2028", "District 2"
--   Karina Moreno -- "Member of the City Council since 2020", "Current term: 2024-2028", "District 1"
--   Gina Nestande -- "Member of the City Council since 2016", "Current term: 2024-2028", "District 3"
--   Jan Harnik -- "Member of the City Council since 2010", "Current term: 2022-2026" (no district line: at large)
-- palmdesert.gov/government/elections: "Voters in Districts 4 and 5 will elect City Council representatives for full
-- four-year terms. This election completes the City's transition to five single-member council districts."
--
-- WHY THE TWO AT-LARGE SEATS ARE MODELLED AS SUCH, AND D4/D5 ARE NOT CREATED HERE (operator decision 2026-11-28,
-- Chris Cantrell: "Exact changeover"). Trubee and Harnik represent the WHOLE city until the December installation, so
-- they sit on a LOCAL district on the city's G4110 outline and every Palm Desert address sees them. District 4 and 5
-- offices are deliberately NOT created yet: an office with no current holder on a polygon is DEAD_GEOGRAPHY to
-- check-address-reachability.mjs (it reads office_current_holder, i.e. TODAY), so creating them now with terms starting
-- 2026-12-10 would turn the master-only reachability gate red for every merge until then. CC_0533 creates them, seats
-- Trubee (D4) and Greenwood (D5), and closes the at-large seats -- in one transaction, on or after 2026-12-10, so no
-- district is ever empty. Cost, accepted: until CC_0533 runs, Greenwood is not shown as "incoming".
--
-- 2026 ELECTION (Riverside ROV, update #27, 2026-11-25) -- for CC_0533:
--   District 4: Evan Trubee 2,240 (57.29%), Jonathon Polly 1,670. District 5: John Greenwood 2,799 (59.76%),
--   Ralph E. Perry 1,885. Harnik was not a candidate.
--
-- POLYGONS (all five loaded now; district rows for D1-D3 only). The city's own layer, linked from its elections page
-- ("Palm Desert Voting Districts Look-Up", cpd.maps.arcgis.com app ad3ac8a3669a4d2d98b35f5c7be33d14): FeatureServer
-- services2.arcgis.com/i4mrGZu1Isvl0rWt/.../Palm_Desert_Voting_Districts_2024/FeatureServer/0, layer name "Adopted
-- Map 109 Renumbered B", owner johnu@cityofpalmdesert.org_CPD, data last edited 2026-07-21. Fetched 2026-11-28 with
-- outSR=4326, 6-dp; file backend/data/seed-palm-desert-2026/palm-desert-council-districts.geojson. X0001 rows
-- 'palm-desert-council-district-N' (the West Covina / Bellflower council-district shape), ST_MakeValid, unsimplified.
-- VINTAGE / LABEL ANCHOR: the layer's own NAME field puts the sitting members on their districts -- "Karina Moreno" on
--   1, "Joe Pradetto" on 2, "Gina Nestande" on 3, blank on 4 and 5 -- matching the city roster above. That ties each
--   polygon's number to a named holder, which a coverage figure cannot do.
-- MEASURED against prod, read-only (EPSG:3310): km2 D1 5.048, D2 22.731, D3 21.533, D4 10.374, D5 10.287; all valid;
--   0 overlapping pairs; union covers 0.99871 (planar) of the G4110 outline; 0.26% of the union lies outside it.
--   City Hall (73510 Fred Waring Dr; Census Geocoder -116.382312, 33.728917) falls in District 1.
--
-- TERMS: open-ended, start_precision 'unknown' (the page gives "since" years and current-term spans, not start days).
-- PEOPLE: no active politician row carried any of the five names on 2026-11-28. external_id -4012301..-4012305 (an
-- unused block; -4012306 is reserved for Greenwood in CC_0533). Party is never stored.
--
-- AFTER APPLYING: this writes geofence_boundaries -> bumps geofence_version (CC_0511). Warm the store, from backend/:
--   npx tsx -e "(async()=>{await import('dotenv/config'); const {warmGeoOverlapPairs}=await import('./src/lib/geoOverlapWarm.ts'); console.log(await warmGeoOverlapPairs()); process.exit(0)})()"
-- Apply with: node scripts/apply-migration-file.mjs migrations/CC_0531_palm_desert_city_government.sql
BEGIN;

-- ─── 0. Preconditions ───
DO $$
DECLARE n int;
BEGIN
  PERFORM 1 FROM essentials.geofence_boundaries WHERE mtfcc = 'G4110' AND geo_id = '0655184';
  IF NOT FOUND THEN RAISE EXCEPTION 'CC_0531 precondition: no G4110 outline for Palm Desert (0655184)'; END IF;
  SELECT count(*) INTO n FROM essentials.governments
   WHERE (geo_id = '0655184' OR name ILIKE 'City of Palm Desert%') AND id <> 'c0cea12c-9699-4379-ab33-81aec487c1ad';
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0531 precondition: another City of Palm Desert government exists (%)', n; END IF;
  SELECT count(*) INTO n FROM essentials.geofence_boundaries
   WHERE mtfcc = 'X0001' AND geo_id LIKE 'palm-desert-council-district-%';
  IF n NOT IN (0, 5) THEN RAISE EXCEPTION 'CC_0531 precondition: % Palm Desert district polygons already exist (expected 0 or 5)', n; END IF;
  SELECT count(*) INTO n FROM essentials.politicians
   WHERE external_id BETWEEN -4012306 AND -4012301
     AND id NOT IN ('27b019ff-125a-473c-9a64-40233ce81968','1fc652aa-4fdd-4ab5-8ab9-cfbaabc21784','be9feaa4-bfeb-404f-b721-14bc4648287a',
                    '6b90bb1b-10f0-42ba-a9ff-be8e601585fe','0edc51b8-8c6b-4897-9b5c-a90587aad946','c70d6462-0dbc-467f-b56b-9b341a845c70');
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0531 precondition: an external_id in -4012306..-4012301 belongs to someone else'; END IF;
END $$;

-- ─── 1. Government and chamber ───
INSERT INTO essentials.governments (id, name, type, state, city, geo_id, mtfcc)
SELECT 'c0cea12c-9699-4379-ab33-81aec487c1ad'::uuid, 'City of Palm Desert, California, US', 'City', 'CA', 'Palm Desert', '0655184', 'G4110'
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments WHERE id = 'c0cea12c-9699-4379-ab33-81aec487c1ad'::uuid);

INSERT INTO essentials.chambers (id, government_id, name, name_formal, official_count, website_url, policy_engagement_level)
SELECT 'a67fdb55-661f-481c-8636-912266a8e6e3'::uuid, 'c0cea12c-9699-4379-ab33-81aec487c1ad'::uuid, 'City Council',
       'Palm Desert City Council', 5, 'https://www.palmdesert.gov/government/city-council', 'full'
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers WHERE id = 'a67fdb55-661f-481c-8636-912266a8e6e3'::uuid);

