CREATE TEMP TABLE cc0531_plan ON COMMIT DROP AS
SELECT unnest(ARRAY['27b019ff-125a-473c-9a64-40233ce81968','1fc652aa-4fdd-4ab5-8ab9-cfbaabc21784','be9feaa4-bfeb-404f-b721-14bc4648287a',
                    '6b90bb1b-10f0-42ba-a9ff-be8e601585fe','0edc51b8-8c6b-4897-9b5c-a90587aad946']::uuid[]) AS politician_id;

-- ▼▼ BLOCK A (backend/migrations/_templates/office_terms_incumbency_guard.sql) ▼▼
-- @incumbency-decision: gated — opens five undated Palm Desert terms (two at-large holdovers, D1-D3); no handover here (CC_0533 does it); none has a race row
CREATE TEMP TABLE incumbency_before ON COMMIT DROP AS
SELECT rc.id              AS race_candidate_id,
       rc.politician_id,
       rc.is_incumbent    AS stored,
       EXISTS (SELECT 1 FROM essentials.office_terms t
                 JOIN essentials.offices o2 ON o2.id = t.office_id
                WHERE t.politician_id = rc.politician_id
                  AND (t.office_id = r.office_id
                       OR (r.seats > 1 AND ro.chamber_id IS NOT NULL AND o2.chamber_id = ro.chamber_id))
                  AND (t.term_start IS NULL OR t.term_start <= e.election_date)
                  AND (t.term_end   IS NULL OR t.term_end   >= e.election_date)
              )            AS expected
  FROM essentials.race_candidates rc
  JOIN essentials.races     r  ON r.id  = rc.race_id
  JOIN essentials.offices   ro ON ro.id = r.office_id
  JOIN essentials.elections e  ON e.id  = r.election_id
 WHERE e.election_date >= CURRENT_DATE - INTERVAL '1 year'
   AND rc.politician_id IS NOT NULL
   AND rc.politician_id IN (SELECT politician_id FROM cc0531_plan);
-- ▲▲ END OF BLOCK A ▲▲

-- ─── 6. Terms (open-ended, start unknown) ───
INSERT INTO essentials.office_terms (office_id, politician_id, term_start, start_precision, how_started, source)
SELECT v.oid, v.pid, NULL, 'unknown', 'elected', 'palmdesert.gov/government/city-council (read 2026-11-28): ' || v.src || ' Start of current tenure not dated. (CC_0531)'
  FROM (VALUES
    ('446c72cc-5ccd-495f-aec1-b1752b151fc1'::uuid, '27b019ff-125a-473c-9a64-40233ce81968'::uuid, 'Mayor (2026), "Current term: 2022-2026", "At-Large".'),
    ('bd0e85af-891c-4aca-9ae2-e8132baf79e3'::uuid, '0edc51b8-8c6b-4897-9b5c-a90587aad946'::uuid, '"Member of the City Council since 2010", "Current term: 2022-2026".'),
    ('abd54af0-1f1e-4fc0-a684-6e6e14d858a0'::uuid, 'be9feaa4-bfeb-404f-b721-14bc4648287a'::uuid, '"Current term: 2024-2028", "District 1".'),
    ('f37f0be4-11f5-417d-8d7a-3efdb3e60fe3'::uuid, '1fc652aa-4fdd-4ab5-8ab9-cfbaabc21784'::uuid, 'Mayor Pro Tem, "Current term: 2024-2028", "District 2".'),
    ('fd5a77d8-d9e6-4105-a547-ffead2f771e6'::uuid, '6b90bb1b-10f0-42ba-a9ff-be8e601585fe'::uuid, '"Current term: 2024-2028", "District 3".')
  ) AS v(oid, pid, src)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = v.oid);

-- ▼▼ BLOCK B ▼▼
DO $$
DECLARE
  v_planned  int;
  v_scoped   int;
  v_people   int;
  v_created  int;
  v_repaired int;
  v_detail   text;
BEGIN
  SELECT count(*) INTO v_planned FROM cc0531_plan;
  SELECT count(DISTINCT politician_id), count(*) INTO v_people, v_scoped FROM incumbency_before;
  IF v_planned = 0 THEN
    RAISE EXCEPTION 'incumbency guard: the plan table is EMPTY, so this gate asserted nothing. '
      'Point it at the politicians whose office_terms rows this migration writes.';
  END IF;
  RAISE NOTICE 'incumbency guard: % person/people planned, % with a race row in the last year (% row(s))',
    v_planned, v_people, v_scoped;

  WITH after_state AS (
    SELECT rc.id              AS race_candidate_id,
           rc.is_incumbent    AS stored,
           EXISTS (SELECT 1 FROM essentials.office_terms t
                     JOIN essentials.offices o2 ON o2.id = t.office_id
                    WHERE t.politician_id = rc.politician_id
                      AND (t.office_id = r.office_id
                           OR (r.seats > 1 AND ro.chamber_id IS NOT NULL AND o2.chamber_id = ro.chamber_id))
                      AND (t.term_start IS NULL OR t.term_start <= e.election_date)
                      AND (t.term_end   IS NULL OR t.term_end   >= e.election_date)
                  )            AS expected
      FROM essentials.race_candidates rc
      JOIN essentials.races     r  ON r.id  = rc.race_id
      JOIN essentials.offices   ro ON ro.id = r.office_id
      JOIN essentials.elections e  ON e.id  = r.election_id
     WHERE rc.id IN (SELECT race_candidate_id FROM incumbency_before)
  ),
  cmp AS (
    SELECT b.race_candidate_id,
           b.politician_id,
           a.stored,
           a.expected,
           (b.stored IS DISTINCT FROM b.expected) AS drifted_before,
           (a.stored IS DISTINCT FROM a.expected) AS drifted_after
      FROM incumbency_before b
      JOIN after_state a USING (race_candidate_id)
  )
  SELECT count(*) FILTER (WHERE NOT c.drifted_before AND c.drifted_after),
         count(*) FILTER (WHERE c.drifted_before AND NOT c.drifted_after),
         string_agg(
           format('    %s — race_candidate %s says is_incumbent=%s, office_terms now say %s',
                  coalesce(p.full_name, '(unnamed)'), c.race_candidate_id, c.stored, c.expected),
           E'\n' ORDER BY coalesce(p.full_name, ''))
           FILTER (WHERE NOT c.drifted_before AND c.drifted_after)
    INTO v_created, v_repaired, v_detail
    FROM cmp c
    LEFT JOIN essentials.politicians p ON p.id = c.politician_id;

  IF v_repaired > 0 THEN
    RAISE NOTICE 'incumbency guard: % race row(s) that drifted BEFORE this migration now agree with office_terms', v_repaired;
  END IF;

  IF v_created > 0 THEN
    RAISE EXCEPTION E'incumbency guard: % race row(s) agreed with essentials.office_terms before this migration and contradict it now.\n%\n\nThis is what `check:incumbency` will say on the NEXT push to master, under somebody else''s name. Settle it here.\n  • Newcomer — the date is right and the race row is wrong. Set race_candidates.is_incumbent = false IN THIS MIGRATION.\n  • Re-elected — the race row is right and the DATE is wrong: you have written their latest term''s start as the start of their whole tenure. Leave term_start NULL, or write the real first term.\nThe two look identical from the predicate. Read the person. See CC_0396''s header for the worked split of seven such rows.',
      v_created, coalesce(v_detail, '    (no detail)');
  END IF;
END $$;
-- ▲▲ END OF BLOCK B ▲▲

-- ─── 7. Post-verify ───
DO $$
DECLARE n int; bad text;
BEGIN
  -- 7a. five valid polygons, no overlaps, union covers the city as measured (planar 0.99871)
  SELECT count(*) INTO n FROM essentials.geofence_boundaries
   WHERE mtfcc = 'X0001' AND geo_id LIKE 'palm-desert-council-district-_' AND state = '06'
     AND public.ST_IsValid(geometry) AND NOT public.ST_IsEmpty(geometry) AND public.GeometryType(geometry) = 'MULTIPOLYGON';
  IF n <> 5 THEN RAISE EXCEPTION 'CC_0531: expected 5 valid district polygons, found %', n; END IF;
  SELECT count(*) INTO n FROM essentials.geofence_boundaries a JOIN essentials.geofence_boundaries b
      ON a.geo_id < b.geo_id AND a.mtfcc = 'X0001' AND b.mtfcc = 'X0001'
   WHERE a.geo_id LIKE 'palm-desert-council-district-_' AND b.geo_id LIKE 'palm-desert-council-district-_'
     AND public.ST_Area(public.ST_Intersection(a.geometry, b.geometry)) > 1e-10;
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0531: % overlapping district pairs', n; END IF;
  PERFORM 1 FROM (
    SELECT public.ST_Area(public.ST_Intersection(u.g, f.geometry)) / public.ST_Area(f.geometry) AS r
      FROM (SELECT public.ST_Union(geometry) g FROM essentials.geofence_boundaries WHERE mtfcc = 'X0001' AND geo_id LIKE 'palm-desert-council-district-_') u,
           essentials.geofence_boundaries f WHERE f.mtfcc = 'G4110' AND f.geo_id = '0655184') x
   WHERE x.r BETWEEN 0.995 AND 1.0;
  IF NOT FOUND THEN RAISE EXCEPTION 'CC_0531: district union no longer covers >= 0.995 of the city outline (measured 0.99871)'; END IF;

  -- 7b. each office: the district and holder the city lists (fields, not counts)
  SELECT string_agg(v.id::text || ' -> ' || coalesce(d.geo_id, 'NULL') || ' / ' || coalesce(p.full_name, 'NULL'), '; ') INTO bad
    FROM (VALUES
      ('446c72cc-5ccd-495f-aec1-b1752b151fc1'::uuid, '0655184', 'G4110', 'Evan Trubee'),
      ('bd0e85af-891c-4aca-9ae2-e8132baf79e3'::uuid, '0655184', 'G4110', 'Jan Harnik'),
      ('abd54af0-1f1e-4fc0-a684-6e6e14d858a0'::uuid, 'palm-desert-council-district-1', 'X0001', 'Karina Moreno'),
      ('f37f0be4-11f5-417d-8d7a-3efdb3e60fe3'::uuid, 'palm-desert-council-district-2', 'X0001', 'Joe Pradetto'),
      ('fd5a77d8-d9e6-4105-a547-ffead2f771e6'::uuid, 'palm-desert-council-district-3', 'X0001', 'Gina Nestande')
    ) AS v(id, geo, mtfcc, holder)
    LEFT JOIN essentials.offices o ON o.id = v.id
    LEFT JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
    LEFT JOIN essentials.politicians p ON p.id = och.politician_id
   WHERE o.id IS NULL OR d.geo_id IS DISTINCT FROM v.geo OR d.mtfcc IS DISTINCT FROM v.mtfcc
      OR p.full_name IS DISTINCT FROM v.holder OR o.chamber_id <> 'a67fdb55-661f-481c-8636-912266a8e6e3'::uuid;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'CC_0531: office/district/holder mismatch: %', bad; END IF;

  -- 7c. no empty district: every district this file created has a current holder (the DEAD_GEOGRAPHY condition)
  SELECT count(*) INTO n FROM essentials.districts d
   WHERE d.id IN ('84f961f9-efcd-4dcb-892a-5deb56a289bd','6674da19-34a7-4db3-ad99-863acea0f8ae','54915b00-635f-4c92-98de-b5999f89b078','784372e6-3c96-4db3-a83c-7b507b649132')
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
                      WHERE o.district_id = d.id AND och.politician_id IS NOT NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0531: % new district(s) have no current holder', n; END IF;

  -- 7d. named-place anchor: City Hall resolves to exactly three council offices -- its district (D1, Moreno) and the two
  --     at-large seats -- through the same geofence -> district join the API uses
  SELECT string_agg(p.full_name, ',' ORDER BY p.full_name) INTO bad
    FROM essentials.geofence_boundaries gb
    JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.mtfcc = gb.mtfcc
    JOIN essentials.offices o ON o.district_id = d.id AND o.chamber_id = 'a67fdb55-661f-481c-8636-912266a8e6e3'::uuid
    JOIN essentials.office_current_holder och ON och.office_id = o.id
    JOIN essentials.politicians p ON p.id = och.politician_id
   WHERE public.ST_Covers(gb.geometry, public.ST_SetSRID(public.ST_MakePoint(-116.382312, 33.728917), 4326));
  IF bad IS DISTINCT FROM 'Evan Trubee,Jan Harnik,Karina Moreno' THEN
    RAISE EXCEPTION 'CC_0531: City Hall resolves to [%], expected Evan Trubee, Jan Harnik, Karina Moreno', bad;
  END IF;

  RAISE NOTICE 'CC_0531 OK: Palm Desert council, 5 polygons, D1-D3 + 2 at-large seated; City Hall -> D1 + at-large';
END $$;

COMMIT;
